statements:
REVOKE ALL PRIVILEGES ON TABLE
  public.bands,
  public.social_links,
  public.events
FROM anon, PUBLIC

REVOKE ALL PRIVILEGES ON TABLE
  public.public_bands,
  public.public_social_links,
  public.public_events
FROM anon, authenticated, service_role, PUBLIC

GRANT SELECT ON TABLE
  public.public_bands,
  public.public_social_links,
  public.public_events
TO anon
